#!/bin/ksh
# MMI3G-Toolkit Uninstaller
# GENERATED by builder/generate_uninstall.py from modules/*/module.json and
# builder/retired_modules.json. Do not edit by hand: change those and re-run it.
# Removes the GEM screens and script folders any toolkit version installed.
# Safe to run even if only some modules were installed: missing items are skipped.

EFSDIR="/mnt/efs-system"
ENGDEFS="${EFSDIR}/engdefs"
SCRIPTS="${EFSDIR}/scripts"

echo "============================================"
echo " MMI3G-Toolkit Uninstaller"
echo " $(date)"
echo "============================================"
echo ""

if [ ! -d "${EFSDIR}" ]; then
    echo "[ERROR] ${EFSDIR} not found. Not running on MMI?"
    exit 1
fi

mount -uw ${EFSDIR}
if [ $? -ne 0 ]; then
    echo "[ERROR] Failed to remount ${EFSDIR} read-write"
    exit 1
fi
echo "[OK] ${EFSDIR} remounted rw"
echo ""

# GEM screens (.esd files in /mnt/efs-system/engdefs): current modules by
# name, earlier versions by pattern.
echo "--- Removing GEM screens ---"
REMOVED_ESD=0
for pattern in \
    "Coding*.esd" \
    "CodingBusRouting.esd" \
    "CodingCarConfig.esd" \
    "CodingMain.esd" \
    "DiagTool*.esd" \
    "GEM*.esd" \
    "GamesMenu*.esd" \
    "GamesMenu.esd" \
    "Gauges*.esd" \
    "GaugesDashboard.esd" \
    "GaugesNetwork.esd" \
    "GaugesSystem.esd" \
    "JVMExtract*.esd" \
    "LTE*.esd" \
    "MapParser*.esd" \
    "NavUnblocker*.esd" \
    "PasswordFinder*.esd" \
    "RegionAuditMain.esd" \
    "Scanner*.esd" \
    "ScannerEngine1.esd" \
    "ScannerEngine2.esd" \
    "ScannerGPS.esd" \
    "ScannerGaps1.esd" \
    "ScannerGaps2.esd" \
    "ScannerMixed.esd" \
    "ScannerPer3Engine.esd" \
    "ScannerPer3Low.esd" \
    "ScannerPer3Mid1.esd" \
    "ScannerStrings.esd" \
    "Splash*.esd" \
    "SystemInfo*.esd" \
    "ToolkitDTC.esd" \
    "ToolkitDiag.esd" \
    "ToolkitMain.esd" \
    "ToolkitSWDL.esd" \
    "VariantDump*.esd"
do
    for f in ${ENGDEFS}/${pattern}; do
        if [ -f "${f}" ]; then
            rm -v "${f}"
            REMOVED_ESD=$((REMOVED_ESD + 1))
        fi
    done
done
echo "  ${REMOVED_ESD} GEM screen(s) removed"
echo ""

# Script folders under /mnt/efs-system/scripts (module.json script_dir, and
# earlier versions' folders).
echo "--- Removing script folders ---"
REMOVED_DIRS=0
for d in \
    Coding \
    DiagTool \
    GEM \
    GEMMI \
    Games \
    Gauges \
    GoogleEarth \
    JVMExtract \
    LTE \
    MapParser \
    NavUnblocker \
    NetDiag \
    PasswordFinder \
    Per3Reader \
    RegionAudit \
    Scanner \
    Splash \
    SystemInfo \
    USBNet \
    VariantDump \
    dtc-checker \
    game-loader \
    long-coding \
    per3-writer
do
    if [ -d "${SCRIPTS}/${d}" ]; then
        rm -rf "${SCRIPTS}/${d}"
        echo "  Removed ${SCRIPTS}/${d}"
        REMOVED_DIRS=$((REMOVED_DIRS + 1))
    fi
done
echo "  ${REMOVED_DIRS} script folder(s) removed"
echo ""

# Changes outside engdefs/scripts are not undone here: each needs its own
# backup or card.
echo "--- Not undone here (each has its own way back) ---"
echo "  gem-activator: the GEM stays enabled: run gem_disable.sh first (GEM or the gem-activator card) if you want it off"
echo "  google-earth-gemmi-wrappers: Use build_sd.py --uninstall to remove /mnt/efs-system/scripts/GEMMI/, or delete that script directory manually."
echo "  google-earth-p0824-deploy: Use build_sd.py --uninstall to remove helper scripts only. Use google-earth-p0824-restore to revert /mnt/nav/gemmi."
echo "  google-earth-p0824-restore: Use this restore card before removing helper scripts with build_sd.py --uninstall."
echo "  google-earth: libembeddedearth.so and the on-car proxy stay: run ge_restore.sh first (it puts back libembeddedearth.so.orig)"
echo "  lte-setup: its network files stay: run lte_restore.sh from the card you installed with (its backup is in var/ there)"
echo "  nav-unblocker: manage_cd.sh stays patched: run nav_restore.sh first (GEM or the nav-unblocker card); the original is kept at /mnt/efs-system/usr/bin/manage_cd.sh-ORIG"
echo "  per3-reader: its bundle stays in the DSITracer.jar slot: run per3_restore.sh first (it puts back DSITracer.jar.bak)"
echo "  region-audit: Use the toolkit uninstall SD or remove the installed engdefs/scripts from /mnt/efs-system. This module writes no custom persistence flags and makes no firmware changes."
echo "  splash-screen: the boot images stay: restore them with splash_restore.sh from the card you installed with (its backup is in var/ there)"
echo "  usb-net: the LAN-mode flag /HBpersistence/DLinkReplacesPPP from its lte mode stays (DrGER's LTE set-up and wifi-sta use it too)"
echo "  wifi-sta: left as it is: build its card with an empty wifi-sta/REMOVE file, which removes the station files, its GEM screen and its start-up block together"
echo ""

sync
mount -ur ${EFSDIR} 2>/dev/null

echo "============================================"
echo " Uninstall complete."
echo " Reboot MMI: hold MENU + knob + upper-right soft key"
echo "============================================"
